codeExample.code:
// 示例：综合使用工具类型和条件类型

// 1. 基础工具类型
interface User {
  id: number;
  name: string;
  email: string;
  age?: number;
  isAdmin: boolean;
}

// 让所有属性变为可选
type PartialUser = Partial<User>;
// 等价于 { id?: number; name?: string; email?: string; age?: number; isAdmin?: boolean }

// 只取 id 和 name
type UserIdName = Pick<User, 'id' | 'name'>;

// 排除 email 和 isAdmin
type UserWithoutSensitive = Omit<User, 'email' | 'isAdmin'>;

// 2. 条件类型与 infer
// 提取 Promise 内部的类型
type Unwrap<T> = T extends Promise<infer U> ? U : T;

// 测试
type ResolvedString = Unwrap<Promise<string>>; // string
type JustNumber = Unwrap<number>; // number

// 提取函数第一个参数的类型
type FirstArgument<T> = T extends (arg: infer A, ...rest: any[]) => any ? A : never;

function greet(name: string, age: number): void {}
type GreetArg = FirstArgument<typeof greet>; // string

// 3. 实际应用：构建类型安全的响应处理器
// 假设我们有一个类似 Redux Action 的结构
type Action =
  | { type: 'ADD_TODO'; payload: { text: string } }
  | { type: 'DELETE_TODO'; payload: { id: number } }
  | { type: 'TOGGLE_TODO'; payload: { id: number } };

// 根据 type 提取对应的 payload 类型
type ExtractPayload<T, ActionType extends string> = 
  T extends { type: ActionType; payload: infer P } ? P : never;

type AddTodoPayload = ExtractPayload<Action, 'ADD_TODO'>; // { text: string }
type DeleteTodoPayload = ExtractPayload<Action, 'DELETE_TODO'>; // { id: number }

// 4. 内置工具类型 Record
// 创建一个以字符串为键，值为 User 的对象
type UserMap = Record<string, User>;
const users: UserMap = {
  '001': { id: 1, name: 'Alice', email: 'alice@example.com', isAdmin: false },
};

